// Sound for the prototypes: the nature-documentary foley generated by
// micro/design/source/build_audio.py (listed in audio-list.js). Ids are
// "<prototype>/<name>", e.g. 'mite/step'. A sound with several takes plays a
// random one each time. Missing files are silent, never an error.
//
//   const audio = createAudio(['mite/amb-moss', 'mite/step', 'mite/dash']);
//   audio.addToFeatures(features);           // Sound and Ambience switches
//   const amb = audio.loop('mite/amb-moss');  // starts once audio is unlocked
//   audio.play('mite/step', { volume: 0.5, rate: 1 + Math.random() * 0.1 });
//   amb.set({ volume: 0.4 });                 // ramps smoothly
//
// Browsers only allow sound after a user gesture; the first key, click, touch
// or controller button unlocks it (the pad is polled by the prototype, so call
// audio.unlock() when any pad button is pressed).
//
// audio.pause() / audio.resume() suspend and resume the whole AudioContext
// (the game pauses its sound with its simulation). audio.setMaster({on,
// volume}) is the game's master switch on top of the Sound effects feature.
// Inside the Micro Zoom shell (embed.js) these follow the shell's `pause`,
// `resume` and `sound` messages by themselves, and window focus is left to
// the shell (focus moves between the shell and the frame; the shell pauses
// when the window loses it), so only a hidden tab silences the page here.
//
// Two sound sets (TEMPORARY: the owner is comparing them; the switch goes
// once one is chosen): 'new' (the default) and 'old', the soundscape before
// the sounds added on 2 November 2026 (audio-list.js ADDED). The shell's
// Settings → Sound effects stores it in localStorage `micro.soundSet` and
// sends it with `sound` ({ soundSet }); a change applies at once. A call says
// what the old set played instead, and the set picks:
//
//   audio.play('mite/jump', { volume: 0.8, old: ['mite/dash', { volume: 0.7, rate: 1.3 }] });
//   audio.play('shared/hit');                        // new only (an ADDED id, no `old`): silent in Old
//   audio.play('mite/bite', { rate: 1.2, only: 'old' }); // a stand-in the new set dropped
//   audio.loop('phage/amb-water', { old: 'bacterium/amb-sediment' });
//   audio.set                                        // 'new' or 'old'
import { SOUNDS, ADDED } from './audio-list.js';
import { embed } from './embed.js';

const base = new URL('../', import.meta.url);
const SET_KEY = 'micro.soundSet';
const readSet = () => { try { return localStorage.getItem(SET_KEY) === 'old' ? 'old' : 'new'; } catch { return 'new'; } };

export function createAudio(ids = Object.keys(SOUNDS)) {
  let ctx = null, master = null, ambBus = null, sfxBus = null;
  let enabled = true, ambience = true;
  let paused = embed.active && embed.paused;
  let masterOn = embed.active ? embed.soundOn : true;
  let masterVol = embed.active ? embed.volume : 1;
  const level = () => (enabled && masterOn && !away ? 0.9 * masterVol : 0);
  const isAway = () => document.hidden || (!embed.active && !document.hasFocus());
  const buffers = new Map(); // id -> Promise<AudioBuffer[]>
  const loops = new Set();
  let soundSet = readSet();
  /** What to play for `id` in the current set: [id, opts] or null (silent). */
  function pick(id, { old, only, ...o } = {}) {
    if (only && only !== soundSet) return null;
    if (soundSet === 'old' && ADDED.has(id)) return old ? [old[0], old[1] || {}] : null;
    return [id, o];
  }
  /** Preload this page's list for the current set (the Old set loads no ADDED sound). */
  const preload = () => { for (const id of ids) if (!(soundSet === 'old' && ADDED.has(id))) load(id); };
  function setSet(v) {
    const s = v === 'old' ? 'old' : 'new';
    if (s === soundSet) return;
    soundSet = s;
    if (ctx) preload();
    for (const l of loops) l._switch();
  }
  addEventListener('storage', (e) => { if (e.key === SET_KEY) setSet(readSet()); });

  function ensure() {
    if (ctx) return ctx;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
    master = ctx.createGain();
    master.gain.value = level();
    master.connect(ctx.destination);
    sfxBus = ctx.createGain(); sfxBus.connect(master);
    ambBus = ctx.createGain(); ambBus.gain.value = ambience ? 1 : 0; ambBus.connect(master);
    preload();
    for (const l of loops) l._start();
    if (paused) ctx.suspend().catch(() => {});
    return ctx;
  }

  function load(id) {
    if (buffers.has(id)) return buffers.get(id);
    const entry = SOUNDS[id];
    const files = entry ? entry.files : [];
    const p = Promise.all(files.map((f) => fetch(new URL(f, base)).then((r) => {
      if (!r.ok) throw new Error(`${r.status} ${f}`);
      return r.arrayBuffer();
    }).then((b) => ctx.decodeAudioData(b)).catch((e) => {
      console.error(`[micro] sound ${id} failed to load: ${e.message}`);
      return null;
    }))).then((list) => list.filter(Boolean));
    buffers.set(id, p);
    return p;
  }

  const unlock = () => {
    if (!ensure()) return;
    if (ctx.state === 'suspended' && !paused && !isAway()) ctx.resume().catch(() => {});
  };
  for (const ev of ['keydown', 'pointerdown', 'touchstart']) addEventListener(ev, unlock, { passive: true });

  // Silent whenever the tab is hidden or the window loses focus; back on return.
  let away = isAway();
  const updateAway = () => {
    away = isAway();
    if (!master) return;
    master.gain.setTargetAtTime(level(), ctx.currentTime, 0.05);
    if ((away || paused) && ctx.state === 'running') ctx.suspend().catch(() => {});
    else if (!away && !paused && ctx.state === 'suspended') ctx.resume().catch(() => {});
  };
  document.addEventListener('visibilitychange', updateAway);
  addEventListener('blur', updateAway);
  addEventListener('focus', updateAway);
  addEventListener('pagehide', updateAway);

  const api = {
    /** Call when a controller button is pressed (gamepads don't fire DOM events). */
    unlock,
    /** Suspend all sound (the game is paused). */
    pause() { paused = true; updateAway(); },
    /** Resume after pause(); also unlocks if a gesture already allowed it. */
    resume() { paused = false; unlock(); updateAway(); },
    get paused() { return paused; },
    /** The game's master switch and volume (0..1), on top of the Sound effects feature. */
    /** The sound set in use: 'new' or 'old' (see the top of this file). */
    get set() { return soundSet; },
    setSet,
    setMaster({ on, volume, soundSet: ss } = {}) {
      if (ss) setSet(ss);
      if (typeof on === 'boolean') masterOn = on;
      if (typeof volume === 'number') masterVol = Math.max(0, Math.min(1, volume));
      if (masterOn && !paused) unlock();
      updateAway();
    },
    get ready() { return !!ctx && ctx.state === 'running'; },
    /** Play a one-shot. Returns nothing; silent if not loaded or disabled. */
    play(id0, opts0) {
      const p = pick(id0, opts0);
      if (!p) return;
      const [id, { volume = 1, rate = 1, pan = 0, delay = 0 } = {}] = p;
      if (!ctx || !enabled || ctx.state !== 'running') return;
      const v = (SOUNDS[id]?.volume ?? 1) * volume;
      load(id).then((list) => {
        if (!list.length) return;
        const src = ctx.createBufferSource();
        src.buffer = list[(Math.random() * list.length) | 0];
        src.playbackRate.value = rate;
        const g = ctx.createGain(); g.gain.value = v;
        let node = src.connect(g);
        if (pan && ctx.createStereoPanner) { const p = ctx.createStereoPanner(); p.pan.value = Math.max(-1, Math.min(1, pan)); node = node.connect(p); }
        node.connect(sfxBus);
        src.start(ctx.currentTime + delay);
      });
    },
    /**
     * A looping sound (ambience or a continuous layer such as the cilia beat).
     * Ids starting with 'amb' go through the Ambience switch.
     * Returns { set({volume, rate}), stop() }.
     */
    loop(id0, { volume = 1, rate = 1, old = null } = {}) {
      // the id for the current set (null: silent in it)
      const want = () => (soundSet === 'old' && ADDED.has(id0) ? old : id0);
      let id = want();
      const isAmb = () => !!id && id.split('/')[1]?.startsWith('amb');
      // sentV / sentR: the last target set() sent, so a world calling set() every
      // frame with the same values doesn't stack identical automation events
      // (re-sending the same target and time constant traces the same curve).
      const state = { volume, rate, src: null, gain: null, stopped: false, sentV: null, sentR: null };
      const handle = {
        /** The sound set changed: fade out this loop's sound and start the other set's. */
        _switch() {
          const w = want();
          if (w === id) return;
          if (state.gain) state.gain.gain.setTargetAtTime(0, ctx.currentTime, 0.2);
          if (state.src) state.src.stop(ctx.currentTime + 1);
          state.src = null; state.gain = null; state.sentV = null; state.sentR = null;
          id = w;
          handle._start();
        },
        _start() {
          if (!ctx || !id || state.src || state.stopped) return;
          const mine = id;
          load(mine).then((list) => {
            if (!list.length || state.src || state.stopped || id !== mine) return;
            const src = ctx.createBufferSource();
            src.buffer = list[0]; src.loop = true; src.playbackRate.value = state.rate;
            const g = ctx.createGain(); g.gain.value = 0;
            g.gain.setTargetAtTime((SOUNDS[id]?.volume ?? 1) * state.volume, ctx.currentTime, 0.4);
            src.connect(g).connect(isAmb() ? ambBus : sfxBus);

            src.start();
            state.src = src; state.gain = g;
            state.sentV = null; state.sentR = null; // the fade-in above is a different curve
          });
        },
        set({ volume: v, rate: r } = {}) {
          if (v !== undefined) state.volume = v;
          if (r !== undefined) state.rate = r;
          const tv = (SOUNDS[id]?.volume ?? 1) * state.volume;
          if (state.gain && tv !== state.sentV) { state.gain.gain.setTargetAtTime(tv, ctx.currentTime, 0.08); state.sentV = tv; }
          if (state.src && state.rate !== state.sentR) { state.src.playbackRate.setTargetAtTime(state.rate, ctx.currentTime, 0.08); state.sentR = state.rate; }
        },
        stop() {
          state.stopped = true; loops.delete(handle);
          state.sentV = null; state.sentR = null;
          if (state.gain) state.gain.gain.setTargetAtTime(0, ctx.currentTime, 0.2);
          if (state.src) state.src.stop(ctx.currentTime + 1);
        },
      };
      loops.add(handle);
      handle._start();
      return handle;
    },
    /** Register Sound and Ambience switches in the feature panel. */
    addToFeatures(features) {
      features.add({ id: 'sound', group: 'Controls', on: true, onChange: (v) => { enabled = v; if (master) master.gain.setTargetAtTime(level(), ctx.currentTime, 0.05); } });
      features.add({ id: 'ambience', group: 'Controls', on: true, onChange: (v) => { ambience = v; if (ambBus) ambBus.gain.setTargetAtTime(v ? 1 : 0, ctx.currentTime, 0.2); } });
    },
  };
  if (embed.active) {
    embed.on('pause', () => api.pause());
    embed.on('resume', () => api.resume());
    embed.on('sound', (d) => api.setMaster(d));
  }
  return api;
}
